			{
				Type: []interface{}{"null"},
				Name: "",
			},
			{
				Type: []interface{}{schemaBytes[0]},
				Name: schemaBytes[1],
			},
		},
	}, 4, "\t")
	if err != nil {
		return nil, err
	}

